SELECT percentile_cont(0.95) within GROUP (ORDER BY (o.dischtime - o.intime)) AS percentile_95, corr(o.los, p.dod) AS correlation_los_dod, corr(o.los, p.gender) AS correlation_los_gender, corr(o.los, p.anchor_age) AS correlation_los_anchor_age FROM icustays o JOIN patients p ON o.subject_id = p.subject_id WHERE p.gender = 2 AND p.anchor_age BETWEEN 56 AND 66 AND p.dod IS NOT NULL AND p.icd_code = '341500' AND o.intime <= '2020-01-01' AND o.dischtime >= '2020-12-31' AND o.hadm_id IN (SELECT hadm_id FROM admissions WHERE admission_type = 'ICU');